import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { SignupForm } from "./SignupForm";

function deferred<T = void>() {
  let resolve!: (value: T) => void;
  const promise = new Promise<T>((res) => {
    resolve = res;
  });
  return { promise, resolve };
}

const valid = {
  email: "jane@example.com",
  password: "correct-horse-battery",
  confirm: "correct-horse-battery",
};

describe("SignupForm", () => {
  it("shows the email error on blur", async () => {
    const user = userEvent.setup();
    render(<SignupForm onSubmit={vi.fn()} />);

    const email = screen.getByLabelText("Email");
    await user.type(email, "not-an-email");
    expect(email).not.toHaveAttribute("aria-invalid");
    expect(screen.queryByText("Enter a valid email address")).toBeNull();

    await user.tab(); // blurs the email input
    const error = screen.getByText("Enter a valid email address");
    expect(error).toBeInTheDocument();
    expect(error).toHaveAttribute("id", "email-error");
    expect(email).toHaveAttribute("aria-invalid", "true");
  });

  it("clears the field error once fixed on reblur", async () => {
    const user = userEvent.setup();
    render(<SignupForm onSubmit={vi.fn()} />);

    const password = screen.getByLabelText("Password");
    await user.type(password, "short");
    await user.tab();
    expect(screen.getByText("Password must be at least 8 characters")).toBeInTheDocument();

    await user.clear(password);
    await user.type(password, valid.password);
    await user.tab();
    expect(screen.queryByText("Password must be at least 8 characters")).toBeNull();
    expect(password).not.toHaveAttribute("aria-invalid");
  });

  it("blocks submit when confirm does not match and reports the error accessibly", async () => {
    const user = userEvent.setup();
    const onSubmit = vi.fn().mockResolvedValue(undefined);
    render(<SignupForm onSubmit={onSubmit} />);

    await user.type(screen.getByLabelText("Email"), valid.email);
    await user.type(screen.getByLabelText("Password"), valid.password);
    await user.type(screen.getByLabelText("Confirm password"), "different-password");

    await user.click(screen.getByRole("button", { name: "Sign up" }));

    const error = screen.getByText("Passwords do not match");
    expect(error).toBeInTheDocument();

    // aria wiring for the mismatch
    const confirm = screen.getByLabelText("Confirm password");
    expect(confirm).toHaveAttribute("aria-invalid", "true");
    expect(confirm).toHaveAttribute("aria-describedby", "confirm-error");
    expect(document.getElementById("confirm-error")).toContainElement(error);

    // submit never reached onSubmit
    expect(onSubmit).not.toHaveBeenCalled();
  });

  it("disables the submit button while onSubmit is pending and resets fields on success", async () => {
    const user = userEvent.setup();
    const d = deferred();
    const onSubmit = vi.fn().mockReturnValue(d.promise);
    render(<SignupForm onSubmit={onSubmit} />);

    await user.type(screen.getByLabelText("Email"), valid.email);
    await user.type(screen.getByLabelText("Password"), valid.password);
    await user.type(screen.getByLabelText("Confirm password"), valid.confirm);

    const button = screen.getByRole("button", { name: "Sign up" });
    expect(button).toBeEnabled();

    await user.click(button);

    // pending: onSubmit called with values, button disabled
    expect(onSubmit).toHaveBeenCalledTimes(1);
    expect(onSubmit).toHaveBeenCalledWith(valid);
    expect(button).toBeDisabled();

    // resolve manually
    d.resolve();
    await vi.waitFor(() => expect(button).toBeEnabled());
    expect(await screen.findByRole("button", { name: "Sign up" })).toBeEnabled();

    // form reset after success
    expect(screen.getByLabelText("Email")).toHaveValue("");
    expect(screen.getByLabelText("Password")).toHaveValue("");
    expect(screen.getByLabelText("Confirm password")).toHaveValue("");
  });

  it("wires labels, roles and describedby relationships correctly", async () => {
    const user = userEvent.setup();
    render(<SignupForm onSubmit={vi.fn()} />);

    // getByRole textbox lookups only work if <label htmlFor> is wired
    const email = screen.getByRole("textbox", { name: "Email" });
    const password = screen.getByLabelText(/Password/); // disambiguated below
    const confirm = screen.getByRole("textbox", { name: /confirm/i });

    expect(email).toHaveAttribute("type", "email");
    expect(confirm).toHaveAttribute("id", "confirm");

    // no errors initially -> no aria-describedby / aria-invalid anywhere
    expect(
      document.querySelectorAll("[aria-describedby], [aria-invalid]")
    ).toHaveLength(0);

    // trigger errors on all three fields
    await user.type(email, "bad");
    await user.tab();
    await user.type(password as HTMLElement, "short");
    await user.tab();
    await user.type(confirm, "nope");
    await user.click(screen.getByRole("button", { name: "Sign up" }));

    for (const [field, id] of [
      ["email", "email-error"],
      ["password", "password-error"],
      ["confirm", "confirm-error"],
    ] as const) {
      const input = document.getElementById(field)!;
      expect(input).toHaveAttribute("aria-invalid", "true");
      expect(input.getAttribute("aria-describedby")).toBe(id);
      const describedBy = document.getElementById(id);
      expect(describedBy).not.toBeNull();
      expect(describedBy!.getAttribute("role")).toBe("alert");
      expect(input.getAttribute("aria-describedby")!).toBeTruthy();
    }

    // describedby ids point at elements that actually contain the messages
    expect(document.getElementById("email-error")?.textContent).toBe(
      "Enter a valid email address"
    );
    expect(document.getElementById("password-error")?.textContent).toBe(
      "Password must be at least 8 characters"
    );
    expect(document.getElementById("confirm-error")?.textContent).toBe(
      "Passwords do not match"
    );
  });

  it("submits successfully when all fields are valid", async () => {
    const user = userEvent.setup();
    const onSubmit = vi.fn().mockResolvedValue(undefined);
    render(<SignupForm onSubmit={onSubmit} />);

    await user.type(screen.getByLabelText("Email"), valid.email);
    await user.type(screen.getByLabelText("Password"), valid.password);
    await user.type(screen.getByLabelText("Confirm password"), valid.confirm);
    await user.click(screen.getByRole("button", { name: "Sign up" }));

    expect(onSubmit).toHaveBeenCalledWith(valid);
  });
});
"})
